create function pg_temp.payroll_prepare(key text default 'payroll-acceptance-one', evidence jsonb default pg_temp.payroll_evidence()) returns uuid language sql as $$select public.prepare_books_payroll_import('99400000-0000-4000-8000-000000000001','99400000-0000-4000-8000-000000000050',evidence,'Reviewed provider register and allocation controls',key)$$;
select ok(not has_table_privilege('authenticated','public.books_payroll_imports','select'),'private payroll registers deny browser reads');
select ok(not has_function_privilege('anon','public.prepare_books_payroll_import(uuid,uuid,jsonb,text,text)','execute'),'anonymous preparation denied');
select ok(not has_function_privilege('authenticated','public.review_books_payroll_import(uuid,uuid,uuid,jsonb,text)','execute'),'browser review RPC denied');
select lives_ok($$select pg_temp.payroll_prepare()$$,'prepare exact immutable evidence');
select is(pg_temp.payroll_prepare(),'99400000-0000-4000-8000-000000000006'::uuid,'matching retry returns original draft');
select throws_like($$select public.review_books_payroll_import('99400000-0000-4000-8000-000000000001','99400000-0000-4000-8000-000000000006','99400000-0000-4000-8000-000000000050',pg_temp.payroll_evidence(),'Self review attempted on payroll evidence')$$,'%separate active reviewer%','preparer cannot self review');
select throws_like($$select pg_temp.payroll_prepare('changed-payroll-controls',jsonb_set(pg_temp.payroll_evidence(),'{run,controls,gross_cents}','24001'))$$,'%control total differs%','provider control mismatch is rejected');
select throws_like($$update public.books_payroll_imports set preparation_notes='Changed original preparation notes' where id='99400000-0000-4000-8000-000000000006'$$,'%evidence is immutable%','preparation evidence is immutable');
select lives_ok($$select public.review_books_payroll_import('99400000-0000-4000-8000-000000000001','99400000-0000-4000-8000-000000000006','99400000-0000-4000-8000-000000000051',pg_temp.payroll_evidence(),'Independent review of source and allocation evidence')$$,'independent review succeeds');
select is((select status from public.books_payroll_imports where id='99400000-0000-4000-8000-000000000006'),'reviewed','reviewed state is retained without posting GL');
select throws_like($$select pg_temp.payroll_prepare('overlapping-payroll-run',jsonb_set(pg_temp.payroll_evidence(),'{run,id}','"99400000-0000-4000-8000-000000000060"'))$$,'%already reserved%','worker period cannot be imported twice');
select throws_like($$delete from public.doc_versions where id='99400000-0000-4000-8000-000000000007'$$,'%Payroll original document version evidence is immutable%','original version cannot be deleted');
select throws_like($$update public.files set checksum=repeat('f',64) where id='99400000-0000-4000-8000-000000000008'$$,'%Payroll original object metadata is immutable%','same original path cannot change checksum');
select lives_ok($$select public.withdraw_books_payroll_import('99400000-0000-4000-8000-000000000001','99400000-0000-4000-8000-000000000006','99400000-0000-4000-8000-000000000050','Replaced after reviewed payroll source correction')$$,'reviewed unposted run can be withdrawn');
select is((select reviewed_by from public.books_payroll_imports where id='99400000-0000-4000-8000-000000000006'),'99400000-0000-4000-8000-000000000051'::uuid,'withdrawal retains independent reviewer');
select throws_like($$delete from public.books_payroll_imports where id='99400000-0000-4000-8000-000000000006'$$,'%history cannot be deleted%','withdrawal keeps immutable payroll history');
select throws_like($$delete from public.doc_versions where id='99400000-0000-4000-8000-000000000007'$$,'%Payroll original document version evidence is immutable%','withdrawn run retains original source protection');
select isnt(public.books_payroll_source_revision(jsonb_set(public.capture_books_export_snapshot('99400000-0000-4000-8000-000000000001'),'{tables,time_entries}','[{"id":"99400000-0000-4000-8000-000000000062","org_id":"99400000-0000-4000-8000-000000000001","worker_user_id":"99400000-0000-4000-8000-000000000002","work_date":"2026-09-10"}]'),pg_temp.payroll_evidence()->'run'),pg_temp.payroll_evidence()->>'source_revision','new worker time invalidates payroll evidence');
select is(public.capture_books_payroll_context('99400000-0000-4000-8000-000000000001',pg_temp.payroll_evidence()->'run')->>'payrollSourceRevision',pg_temp.payroll_evidence()->>'source_revision','native payroll context carries its statement revision');
